  const base=Math.floor(stock/combinations.length),remainder=stock%combinations.length;
  const variants=combinations.map(({size,color,index})=>({id:variantKey(size,color),size,color,sku:`${sku}-${index+1}`,stock:base+(index<remainder?1:0)}));
  const obj={id:`prd-${Date.now()}-${Math.random().toString(36).slice(2,7)}`,name,slug,category:categoryId,price,oldPrice,discountPercent:oldPrice>price&&oldPrice?Math.round((oldPrice-price)*100/oldPrice):0,sku,brand:'',sizes,colors,variants,stock,images:image?[image]:[],shortDesc:form.elements.shortDesc.value.trim(),longDesc:'',desc:'',features:[],specifications:{سایزبندی:sizes.join('، ')},featured:false,bestSeller:false,active,image:0,createdAt:now,updatedAt:now};
